export type ParsedEnterInstruction<
  TProgram extends string = typeof ARENA_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    entrant: TAccountMetas[0];
    round: TAccountMetas[1];
    entry: TAccountMetas[2];
    /**
     * Checked against the round's own vault key so a caller cannot pay their
     * fee into an account they control and still get an entry.
     */
    vault: TAccountMetas[3];
    entrantTokens: TAccountMetas[4];
    tokenProgram: TAccountMetas[5];
    systemProgram: TAccountMetas[6];
  };
  data: EnterInstructionData;
};

export function parseEnterInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedEnterInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 7) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 7,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      entrant: getNextAccount(),
      round: getNextAccount(),
      entry: getNextAccount(),
      vault: getNextAccount(),
      entrantTokens: getNextAccount(),
      tokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
    },
    data: getEnterInstructionDataDecoder().decode(instruction.data),
  };
}
